pergunta:
O resultado de "selectPixels" já seleciona apenas o resultado comum entre as bandas ou apenas mosaica o resultado individual de cada banda ? Caso seja a primeira opção, aplique ".reduceCount()" e em sequência o ".updateMask()" sendo a segunda imagem com a quantidade de bandas (no exemplo abaixo, seriam seis). Com essa abordagem apenas as áreas comuns as seis imagens seriam selecionadas. Aqui está o script para análise: Map.setOptions('SATELLITE'); // 'ROADMAP', 'SATELLITE', 'HYBRID' ou 'TERRAIN'

// Importar a coleção Planet NICFI Americas
var nicfi = ee.ImageCollection('projects/planet-nicfi/assets/basemaps/americas')
  .map(function(img) {
    return img.clip(geometry2);
  });

print(nicfi.limit(10), 'nicfi');

// Bandas da coleção
var BandsMatas = ee.List([
  'B', 
  'G', 
  'R', 
  'N', 
  'NDVI', 
  'NDWI'
]);

// Adicionar função para calcular NDVI
function calculateNDVI(image) {
  var ndvi = image.normalizedDifference(['N', 'R']).rename('NDVI');
  return image.addBands(ndvi).copyProperties(image, ['system:time_start']);
}

// Adicionar função para calcular NDWI
function calculateNDWI(image) {
  var ndwi = image.normalizedDifference(['N', 'B']).rename('NDWI');//'G', 'N'
  return image.addBands(ndwi).copyProperties(image, ['system:time_start']);
}

// Filtrar a coleção de mapas base por data e adicionar NDVI e NDWI
var filteredImages = nicfi
  .filter(ee.Filter.date('2015-01-01', '2024-12-31'))
  .map(calculateNDVI)
  .map(calculateNDWI);

// Redução dos percentis
var x3 = filteredImages.reduce(ee.Reducer.percentile([30]));

var BandsX = ee.List([
  'B_p30', 
  'G_p30', 
  'R_p30', 
  'N_p30', 
  'NDVI_p30', 
  'NDWI_p30'
]);

//print(BandsX, 'BandsX');

// Reduzir a região para obter os valores de pixel
var x2 = x3.reduceRegion({
  reducer: ee.Reducer.toList(),
  geometry: InteresseArenizacao,//Interesse,
  scale: 5,
  maxPixels: 1e13,
  tileScale: 16
});

//print(x2, 'x2');

var x2teste = x3.reduceRegion({
  reducer: ee.Reducer.toList(),
  geometry: removerArenizacao,//geometryRemover,
  scale: 5,
  maxPixels: 1e13,
  tileScale: 16
});


//print(x2teste, 'x2teste');

// Função para remover elementos de uma lista de outra lista
function removerElementos(listaPrincipal, listaRemover) {
  var setPrincipal = ee.List(listaPrincipal).distinct().sort(); // Garantir listas distintas
  var setRemover = ee.List(listaRemover).distinct().sort();

  var listaFinal = setPrincipal.removeAll(setRemover);

  return listaFinal;
}

// Função para remover elementos repetidos entre duas listas de dicionários de pixels
function removerlistadelista(principal, remover, bandas) {
  var result = ee.Dictionary(bandas.iterate(function(band, current) {
    band = ee.String(band);
    current = ee.Dictionary(current);
    var listPrincipal = ee.List(principal.get(band)).distinct(); // Garantir listas distintas
    var listRemover = ee.List(remover.get(band)).distinct();
    var filteredList = removerElementos(listPrincipal, listRemover);
    return current.set(band, filteredList);
  }, ee.Dictionary({})));
  return result;
}

var valoresFiltrados = removerlistadelista(x2, x2teste, BandsX);

// Define uma função para selecionar os pixels cujos valores estão na lista para cada banda
function selectPixels(image, valuesDict, bandsList) {
  var masks = bandsList.map(function(band) {
    var bandName = ee.String(band);
    var valuesList = ee.List(valuesDict.get(bandName));
    var individualMasks = valuesList.map(function(val) {
      return image.select([bandName]).eq(ee.Number(val)).selfMask();
    });
    // Combine todas as máscaras individuais utilizando uma combinação de OR lógico por banda
    var combinedBandMask = ee.ImageCollection.fromImages(individualMasks).mosaic();
    return combinedBandMask.rename('teste');
  });

  // Combine todas as máscaras de bandas utilizando um AND lógico que requer todas as bandas estejam presentes
  var combinedTotalMask = ee.ImageCollection.fromImages(masks).toBands().reduce(ee.Reducer.allNonZero());

  return image.updateMask(combinedTotalMask);
}

// Aplicar a função de seleção de pixels
var maskedImage = selectPixels(x3, valoresFiltrados, BandsX);

// Contar os pixels
var teste_count = maskedImage.reduce(ee.Reducer.count());

print(teste_count, 'teste_count');

Map.addLayer(x3, {bands: ['R_p30', 'G_p30', 'B_p30'], min: 0, max: 1500}, 'Original Image');

Map.addLayer(teste_count, {
  min: 1, max: 54,
  palette: ['#9400D3','#4B0082','#0000FF','#00FF00','#FFFF00','#FF7F00','#FF0000']
}, 'Area interesse', true);

